// Clasificación inteligente de la gravedad y código de error
const errorData = $input.item.json.execution.error;
const workflowName = $input.item.json.workflow.name;
const executionId = $input.item.json.execution.id;

let errorCode = 'ERR_DESCONOCIDO';
let gravedad = 'MEDIA';
const msg = errorData.message || 'Error no especificado';

if (msg.includes('connect') || msg.includes('timeout') || msg.includes('ECONNREFUSED')) {
  errorCode = 'FALLO_CONEXION_SUPABASE';
  gravedad = 'ALTA';
} else if (msg.includes('Excel') || msg.includes('formato') || msg.includes('columna')) {
  errorCode = 'ARCHIVO_INVALIDO_O_CORRUPTO';
  gravedad = 'CRITICA';
} else if (msg.includes('SMTP') || msg.includes('mail') || msg.includes('destinatario')) {
  errorCode = 'FALLO_ENVIO_CORREO';
  gravedad = 'MEDIA';
} else if (msg.includes('AI') || msg.includes('Gemini') || msg.includes('quota')) {
  errorCode = 'FALLO_PROVEEDOR_IA';
  gravedad = 'BAJA'; // La regla determinista continúa aun sin IA
}

return {
  json: {
    executionId,
    workflowName,
    errorCode,
    gravedad,
    mensaje: msg,
    stackTrace: errorData.stack || JSON.stringify(errorData),
    fecha: new Date().toISOString()
  }
};
